<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#61AFEF;"> mask_record</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;font-style:italic;">self</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">record</span><span style="color:#ABB2BF;">: </span><span style="color:#56B6C2;">dict</span><span style="color:#ABB2BF;">) -&gt; </span><span style="color:#56B6C2;">dict</span><span style="color:#ABB2BF;">:</span></span>
